        {"상황":"자신만을 위해 사는 삶에서 의미를 잃은 성도", "성경원리":"타인의 유익을 위해 사는 것이 진정한 삶의 의미를 준다 (빌 1:24)", "실제적용":"타인을 위한 구체적인 섬김을 시작하도록 돕기—교회 봉사, 이웃 돕기, 멘토링 등"}
