        {"새찬송가":"찬송가 321장", "통일찬송가":"찬송가 324장", "제목":"이 몸의 소망 무엔가", "선정이유":"자신의 생명보다 그리스도를 우선시하는 헌신을 고백하는 찬송"},
        {"새찬송가":"찬송가 찾을 수 없는 곡", "통일찬송가":"찬송가 406장", "제목":"나 이제 주님의 새 생명 얻은 몸", "선정이유":"그리스도 안에서 새 생명을 얻어 그를 위해 헌신하는 내용으로 에바브로디도의 헌신 동기를 반영"},
        {"새찬송가":"찬송가 370장", "통일찬송가":"찬송가 419장", "제목":"나 주를 멀리 떠났다", "선정이유":"자기 목숨을 돌아보지 않고 헌신하는 삶으로 돌아오는 결단을 노래하는 찬송으로 설교 마무리에 적합"}
