        {"상황":"능력 부족으로 인한 좌절", "성경원리":"육체를 신뢰하지 않음 - 인간적 한계가 하나님의 역사의 시작점", "실제적용":"고후 12:9-10을 묵상하며 나의 약함을 인정하고 하나님께 맡기는 기도"}
