        {"항목":"5절과의 연결", "내용":"4절은 5-6절에 이어질 바울의 자격 목록 열거의 서두 역할을 함", "목회적활용":"자격을 인정한 후 포기하는 것이 진정한 복음 이해임을 가르침"}
