    표5_매튜헨리: [
        {"영어원문":"Paul here shows that he had as much room to trust in external privileges as any of those who did trust in them, and more too.", "한국어번역":"바울은 외적 특권을 신뢰하는 자들 중 누구보다 더 신뢰할 만한 근거를 가지고 있었음을 여기서 보여줍니다.", "핵심통찰":"바울의 포기는 무지에서가 아닌 알고도 선택한 것이기에 더욱 강력"},
        {"영어원문":"If any man's confidence in the flesh was well-grounded, Paul's was: he was of the stock of Israel, and more; he had been a zealous persecutor.", "한국어번역":"만일 누군가의 육체에 대한 신뢰가 근거 있는 것이라면 바울의 것이 그러했습니다. 그는 이스라엘 족속이었고 더 나아가 열렬한 박해자이기도 했습니다.", "핵심통찰":"최고의 종교적 자격을 가진 자가 그것을 포기할 때 복음의 충분성이 증명됨"},
        {"영어원문":"He does not deny that these were real advantages in some respects, but he denies that they were any ground of confidence for justification before God.", "한국어번역":"바울은 이러한 것들이 어떤 면에서 실제적 유익임을 부정하지 않으나, 하나님 앞에서 칭의의 근거가 된다는 것은 부정합니다.", "핵심통찰":"세상적 유익과 구원의 근거는 별개. 인간적 조건은 은혜 앞에 무력"}
    ],
