        {"영어원문":"As touching the law, a Pharisee; one who was not only instructed in the law, but was of a sect which made more than ordinary profession of strictness.", "한국어번역":"율법에 관해서는 바리새인으로, 율법을 배웠을 뿐 아니라 통상 이상의 엄격함을 표방하는 분파에 속한 자였다.", "핵심통찰":"종교적 엄격함과 지식이 구원을 보장하지 못함을 바울 자신의 경험으로 증거함"}
